import { io } from "socket.io-client";
import { store } from '@/store/index.js'

const socket = io(store.state.api, {
  autoConnect: false,
  transports: ["websocket"],
  reconnection: true,
  reconnectionAttempts: 5,
  reconnectionDelay: 1000,
  timeout: 10000
});

// 连接管理
export function connectSocket() {
  if (socket.connected) return;
  
  const username = localStorage.getItem('UresName');
  if (!username) {
    console.error('无法建立连接: 缺少用户名');
    return;
  }
  
  socket.auth = { username };
  socket.connect();
  
  socket.on('connect', () => {
    console.log('Socket连接成功');
    socket.emit("user_login", { username });
  });
  
  // 处理在线用户更新
  socket.on('online_users_update', (data) => {
    store.commit('setOnlineUsers', data.online_users);
  });
  
  // 处理当前在线用户列表
  socket.on('current_online_users', (data) => {
    store.commit('setOnlineUsers', data.online_users);
  });
  
  // 处理断开连接
  socket.on('disconnect', (reason) => {
    console.log(`连接断开: ${reason}`);
    store.commit('clearOnlineUsers');
    
    // 如果是意外断开，尝试重新连接
    if (reason !== 'io client disconnect') {
      setTimeout(() => socket.connect(), 2000);
    }
  });
}

// 显式登出
export function logoutSocket() {
  const username = localStorage.getItem('UresName');
  if (!username) return;
  
  if (socket.connected) {
    // 发送登出请求
    socket.emit('user_logout', { username }, () => {
      // 确保断开连接
      socket.disconnect();
      console.log('用户已登出');
    });
  } else {
    // 如果未连接，直接清除状态
    store.commit('clearOnlineUsers');
  }
}

// 错误处理
socket.on('connect_error', (err) => {
  console.error('连接错误:', err.message);
});

export default { connectSocket, logoutSocket, socket };
